import{_ as a,o as e,c as r,a3 as t}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Filtro por trechos no campo de novo localizador","description":"","frontmatter":{"title":"Filtro por trechos no campo de novo localizador","id":"eproc-filtro-novo-localizador","plataforma":"eproc","grupo":"Pesquisa e filtros","plano":"free","desde":"1.0.10","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-filtro-novo-localizador.md","filePath":"funcionalidades/eproc-filtro-novo-localizador.md"}'),l={name:"funcionalidades/eproc-filtro-novo-localizador.md"};function s(i,o,c,d,n,p){return e(),r("div",null,o[0]||(o[0]=[t('<h1 id="filtro-por-trechos-no-campo-de-novo-localizador" tabindex="-1">Filtro por trechos no campo de novo localizador <a class="header-anchor" href="#filtro-por-trechos-no-campo-de-novo-localizador" aria-label="Permalink to &quot;Filtro por trechos no campo de novo localizador&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Acrescenta uma busca ao campo <strong>Novo localizador</strong>, em qualquer tela do eproc em que ele apareça. Você digita trechos de palavras, em qualquer ordem, e a lista mostra os localizadores que combinam, com os mais relevantes primeiro.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, campo &quot;Novo localizador&quot; (por exemplo, no cadastro de minuta).</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Clique no campo &quot;Novo localizador&quot;. No lugar da lista comum, abre um painel com campo de busca.</li><li>Digite trechos, por exemplo <code>concl emenda</code>.</li><li>Escolha o localizador na lista filtrada.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Busca aproximada (tolera abreviações e pequenos erros de digitação, mostrando primeiro os resultados mais relevantes)</td><td>ligada</td><td>Também encontra localizadores com pequenas diferenças de grafia e ordena pelo mais parecido.</td></tr></tbody></table><p>A busca por vários trechos em qualquer ordem depende de <a href="./eploc-filtro-localizador-secundario">Filtro por trechos no campo de localizador secundário</a> estar ligado. Com ele desligado, este campo só encontra um trecho contínuo.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Os demais campos de seleção do eproc têm busca própria em <a href="./eproc-filtro-selects">Busca nos campos de seleção</a>.</li></ul>',12)]))}const h=a(l,[["render",s]]);export{u as __pageData,h as default};
